package com.bookstore.book.entity;
import com.bookstore.category.entity.Category; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.time.LocalDateTime;
@Entity @Table(name="books") public class Book { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String title; @Column(nullable=false) private String author; @Column(nullable=false,precision=12,scale=2) private BigDecimal price; @Column(nullable=false) private Integer stock; @Column private String isbn; @Column(columnDefinition="TEXT") private String description; @Column(name="image_url") private String imageUrl; @Column(name="publication_date") private LocalDate publicationDate; @Column(name="created_at") private LocalDateTime createdAt=LocalDateTime.now(); @Column(name="updated_at") private LocalDateTime updatedAt=LocalDateTime.now(); @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="category_id") private Category category;
 public Book() {} public Long getId(){return id;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getAuthor(){return author;} public void setAuthor(String v){author=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public Integer getStock(){return stock;} public void setStock(Integer v){stock=v;} public Category getCategory(){return category;} public void setCategory(Category v){category=v;} public String getIsbn(){return isbn;} public void setIsbn(String v){isbn=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public LocalDate getPublicationDate(){return publicationDate;} public void setPublicationDate(LocalDate v){publicationDate=v;} }
